SELECT /* LGVPAY00015.retrieveAggregateList */ pia.payroll_item_aggregate_id , pia.payroll_item_aggregate_name /*"Aggregate Name"*/ , pia.detail_desc /*"Description"*/ , pia.payroll_aggregate_type_code , cccm.common_code_name AS payroll_aggregate_type_name /*"Aggregate Type"*/ , nvl(max(DECODE(piac.aggregate_cycle_type_code, 'RUN' , 'Y',NULL)),'N') AS run_flag /*"Run"*/ , nvl(max(DECODE(piac.aggregate_cycle_type_code, 'MONTH', 'Y',NULL)),'N') AS month_flag /*"Month"*/ , nvl(max(DECODE(piac.aggregate_cycle_type_code, 'YEAR' , 'Y',NULL)),'N') AS year_flag /*"Year"*/ , NVL(( SELECT 'Y' FROM dual WHERE EXISTS ( SELECT 1 FROM tb_pay_calc_aggr_result_n pcar WHERE pcar.payroll_item_aggregate_id=pia.payroll_item_aggregate_id) ), 'N') AS used_flag /*"used_flag"*/ FROM tb_pay_item_aggr_n pia , lgcom_common_code_multi_lang_c cccm , tb_pay_item_aggr_cycle_n piac WHERE pia.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
AND pia.payroll_item_aggregate_id = #{srchPayrollItemAggregateId, jdbcType=NUMERIC}
AND pia.payroll_item_aggregate_name LIKE '%'||#{payrollItemAggregateName}||'%'
AND cccm.code_type_code = 'LGDVHR_PAY_AGGR_TYPE_CODE' AND cccm.common_code = pia.payroll_aggregate_type_code AND cccm.language_code = #{USER_SESSION.languageCode} AND piac.payroll_item_aggregate_id = pia.payroll_item_aggregate_id GROUP BY pia.payroll_item_aggregate_id , pia.payroll_item_aggregate_name , pia.detail_desc , pia.payroll_aggregate_type_code , cccm.common_code_name ORDER BY pia.payroll_item_aggregate_name
